package main
import("context";"fmt";"os";"github.com/jackc/pgx/v5")
func main(){c:=context.Background();p,e:=pgx.Connect(c,os.Getenv("DATABASE_URL"));if e!=nil{panic(e)};defer p.Close(c);var b []byte;e=p.QueryRow(c,`select jsonb_build_object('recording_id',h.recording_id,'job_id',h.job_id,'local_date',(h.window_start_at at time zone r.cron_timezone)::date,'metric_version',h.metric_version,'calculated_at',h.calculated_at,'clip_count',h.clip_count,'coverage_pct',h.coverage_pct,'largest_gap_seconds',h.largest_gap_seconds,'gap_over_30s_count',h.gap_over_30s_count,'gap_over_5m_count',h.gap_over_5m_count,'overlap_count',h.overlap_count) from recording_window_health h join recordings r on r.id=h.recording_id where h.recording_id=415 order by h.window_start_at desc limit 1`).Scan(&b);if e!=nil{panic(e)};fmt.Println(string(b))}
